CREATE INDEX evaluation_preferences_mode_idx ON evaluation_preferences(mode, buddy_id);
CREATE INDEX decision_requests_task_idx ON decision_requests(task_id);
CREATE INDEX evaluation_decisions_created_idx
    ON evaluation_decisions(created_at, decision_id);
CREATE INDEX macro_tasks_activity_idx ON macro_tasks(activity_seq DESC, macro_task_id DESC);
CREATE INDEX macro_tasks_project_idx ON macro_tasks(project_id, activity_seq DESC, macro_task_id DESC);
CREATE INDEX workflow_runs_state_idx ON workflow_runs(state, updated_at);
CREATE INDEX workflow_runs_macro_task_idx ON workflow_runs(macro_task_id, activity_seq DESC, run_id DESC);
CREATE INDEX workflow_runs_activity_idx ON workflow_runs(activity_seq);
CREATE INDEX workflow_routes_run_idx ON workflow_routes(run_id);
CREATE INDEX workflow_turns_attempt_idx ON workflow_turns(attempt_id);
CREATE INDEX workflow_requests_run_idx ON workflow_requests(run_id, state);
CREATE INDEX workflow_children_parent_idx ON workflow_children(parent_run_id, state);
CREATE INDEX workflow_lead_tasks_lead_idx ON workflow_lead_tasks(lead_run_id);
CREATE INDEX workflow_continuations_run_idx ON workflow_continuations(run_id, state);
CREATE UNIQUE INDEX workflow_continuations_auto_unique
    ON workflow_continuations(run_id, request_id) WHERE kind='helper';
CREATE UNIQUE INDEX workflow_continuations_lead_pending_unique
    ON workflow_continuations(run_id) WHERE kind='lead-wakeup' AND state IN ('recorded','queued');
CREATE UNIQUE INDEX workspace_reservations_writer_unique
    ON workspace_reservations(checkout_id) WHERE state='held' AND access='write';
CREATE INDEX workspace_reservations_checkout_idx ON workspace_reservations(checkout_id, state);
CREATE INDEX workspace_reservations_holder_idx ON workspace_reservations(holder_task_id, state);
CREATE INDEX workflow_workspace_conflicts_run_idx ON workflow_workspace_conflicts(run_id, state);
CREATE INDEX workflow_integrations_run_idx ON workflow_integrations(run_id, artifact_id, created_at);
CREATE INDEX workspace_cleanup_plans_run_idx ON workspace_cleanup_plans(run_id, state);
CREATE UNIQUE INDEX agent_credentials_attempt_unique
    ON agent_credentials(attempt_id) WHERE state='active';
CREATE INDEX agent_credentials_run_idx ON agent_credentials(run_id, state);
CREATE INDEX workflow_artifacts_run_idx ON workflow_artifacts(run_id, created_at);
CREATE INDEX workflow_suggestions_run_idx ON workflow_suggestions(run_id, created_at);
CREATE UNIQUE INDEX workflow_host_conclusions_run_idx ON workflow_host_conclusions(run_id);
CREATE UNIQUE INDEX attempts_router_binding_unique ON attempts(attempt_id, task_id, generation);
CREATE UNIQUE INDEX attempts_router_outcome_binding_unique ON attempts(attempt_id, task_id);
CREATE INDEX router_outcomes_buddy_idx ON router_outcomes(buddy_id, event_seq);
CREATE INDEX router_outcomes_task_idx ON router_outcomes(task_id, event_seq);
CREATE INDEX router_outcomes_attempt_idx ON router_outcomes(attempt_id);
CREATE UNIQUE INDEX attempt_reminders_expected_idx
    ON attempt_reminders(attempt_id, expected_multiple) WHERE kind = 'expected-duration';
CREATE UNIQUE INDEX attempt_reminders_silence_idx
    ON attempt_reminders(attempt_id, silence_started_at) WHERE kind = 'native-silence';
CREATE INDEX workflow_fixes_target_idx ON workflow_fixes(fixed_run_id, created_at);
